// Copyright 2026 Query Farm LLC - https://query.farm

package feedworker

import (
	"context"
	"encoding/json"
	"time"

	"github.com/Query-farm/vgi-go/vgi"
	"github.com/Query-farm/vgi-rpc-go/vgirpc"
	"github.com/apache/arrow-go/v18/arrow"
	"github.com/apache/arrow-go/v18/arrow/array"
	"github.com/apache/arrow-go/v18/arrow/memory"
)

// CatalogName is the VGI catalog name advertised by this worker.
const CatalogName = "feed"

// SampleRSS is a tiny, self-contained RSS 2.0 document used by the catalog
// examples and executable examples. It is parsed directly with NO network
// access, so the examples execute deterministically against an attached worker
// even when no feed server is reachable. It deliberately contains NO single
// quotes so it can be embedded verbatim inside a single-quoted SQL literal.
const SampleRSS = "<rss version=\"2.0\"><channel>" +
	"<title>Query Farm Sample Feed</title>" +
	"<link>https://query.farm/</link>" +
	"<description>A small RSS feed used by vgi-feed examples</description>" +
	"<language>en-us</language>" +
	"<item><title>First Post</title><link>https://query.farm/first</link>" +
	"<category>news</category><category>release</category>" +
	"<description>The first sample entry</description></item>" +
	"<item><title>Second Post</title><link>https://query.farm/second</link>" +
	"<category>news</category>" +
	"<description>The second sample entry</description></item>" +
	"</channel></rss>"

// SamplePreviousRSS is an earlier snapshot of SampleRSS that only carried the
// first entry. Diffing the current SampleRSS against it is the offline stand-in
// for "what is new since I last polled this feed". Like SampleRSS it contains
// NO single quotes.
const SamplePreviousRSS = "<rss version=\"2.0\"><channel>" +
	"<title>Query Farm Sample Feed</title>" +
	"<item><title>First Post</title><link>https://query.farm/first</link></item>" +
	"</channel></rss>"

// Composed examples: each combines two of the worker's objects in one query.
// Every SQL is defined once here and referenced from the schema-level list and
// the driving function's example list. They are NOT in vgi.executable_examples:
// that tag is capped at 4,000 characters (VGI417) and the existing three
// examples plus the inline feed literals already fill it.
const (
	// composedNewEntriesSQL anti-joins two feed_items calls: the current feed
	// against an earlier snapshot, keyed on link. Returns the one new entry
	// (seq 1, Second Post).
	composedNewEntriesSQL = "SELECT cur.seq, cur.title, cur.link " +
		"FROM feed.main.feed_items('" + SampleRSS + "') AS cur " +
		"ANTI JOIN feed.main.feed_items('" + SamplePreviousRSS + "') AS prev ON cur.link = prev.link " +
		"ORDER BY cur.seq"
	composedNewEntriesDesc = "Find the entries that are new since an earlier snapshot of the same feed " +
		"by anti-joining the current feed_items against the snapshot's feed_items on link " +
		"(returns Second Post; no network access)."

	// composedCategoryShareSQL joins feed_info (feed title + reported
	// item_count) to the UNNESTed categories of feed_items, giving each
	// category's entry count and its share of the feed's items. For SampleRSS:
	// news 2 entries (1.0), release 1 entry (0.5).
	composedCategoryShareSQL = "SELECT f.title AS feed_title, c.category, count(*) AS entries, " +
		"round(count(*) / f.item_count, 2) AS share_of_feed " +
		"FROM feed.main.feed_info('" + SampleRSS + "') AS f " +
		"CROSS JOIN (SELECT UNNEST(categories) AS category FROM feed.main.feed_items('" + SampleRSS + "')) AS c " +
		"GROUP BY f.title, f.item_count, c.category " +
		"ORDER BY entries DESC, c.category"
	composedCategoryShareDesc = "Break a feed's entries down by category: join feed_info (feed title and " +
		"reported item_count) to the UNNESTed categories from feed_items to get each category's entry " +
		"count and its share of the feed (news 2 entries = 1.0, release 1 = 0.5; no network access)."
)

// resultColumn is one entry of a vgi.result_columns_schema (VGI321): a returned
// column's name, its DuckDB type, and a non-blank description.
type resultColumn struct {
	Name        string `json:"name"`
	Type        string `json:"type"`
	Description string `json:"description"`
}

func columnsSchemaJSON(cols []resultColumn) string {
	b, err := json.Marshal(cols)
	if err != nil {
		panic(err)
	}
	return string(b)
}

// itemsColumnsSchema / infoColumnsSchema are the static result schemas for the
// two table functions. They MUST match what Process emits (VGI910 checks this
// under --execute): itemsSchema and infoSchema respectively.
var itemsColumnsSchema = columnsSchemaJSON([]resultColumn{
	{"seq", "BIGINT", "0-based position of the item within the feed."},
	{"guid", "VARCHAR", "Item GUID / id (empty string when the feed omits one)."},
	{"title", "VARCHAR", "Item title (empty string when absent)."},
	{"link", "VARCHAR", "Item link / permalink URL (empty string when absent)."},
	{"published", "TIMESTAMP", "Publish time in UTC; NULL when absent or unparseable."},
	{"updated", "TIMESTAMP", "Last-updated time in UTC; NULL when absent or unparseable."},
	{"author", "VARCHAR", "Author display name or email (empty string when absent)."},
	{"categories", "VARCHAR[]", "Item categories / tags as a list (empty list when none)."},
	{"summary", "VARCHAR", "Item summary / description (empty string when absent)."},
	{"content", "VARCHAR", "Full item content (empty string when not provided)."},
})

var infoColumnsSchema = columnsSchemaJSON([]resultColumn{
	{"title", "VARCHAR", "Feed title (empty string when absent)."},
	{"description", "VARCHAR", "Feed description / subtitle (empty string when absent)."},
	{"link", "VARCHAR", "Feed home / site URL (empty string when absent)."},
	{"feed_type", "VARCHAR", "Detected feed format: rss, atom, or json."},
	{"language", "VARCHAR", "Feed language code such as en-us (empty string when absent)."},
	{"updated", "TIMESTAMP", "Feed last-updated time in UTC; NULL when absent or unparseable."},
	{"item_count", "INTEGER", "Number of items present in the feed."},
})

// executableExamples is the VGI509 guaranteed-runnable, catalog-qualified
// example set. Every sql is self-contained, re-runnable against an attached
// feed worker, and parses inline RSS text so it needs no network. We omit
// expected_result deliberately — the linter only needs each query to execute
// cleanly. It is JSON-marshalled from structs so the embedded RSS literal
// (which contains double quotes from version="2.0") is correctly escaped.
var executableExamples = buildExecutableExamples()

func buildExecutableExamples() string {
	type example struct {
		Description string `json:"description"`
		SQL         string `json:"sql"`
	}
	examples := []example{
		{
			Description: "List the items parsed from an inline RSS 2.0 feed, ordered by position.",
			SQL:         "SELECT seq, title, link FROM feed.main.feed_items('" + SampleRSS + "') ORDER BY seq",
		},
		{
			Description: "Expand each item's categories into one row per (item, category).",
			SQL:         "SELECT title, UNNEST(categories) AS category FROM feed.main.feed_items('" + SampleRSS + "') ORDER BY seq",
		},
		{
			Description: "Read feed-level metadata: title, detected format, language, and item count.",
			SQL:         "SELECT title, feed_type, language, item_count FROM feed.main.feed_info('" + SampleRSS + "')",
		},
	}
	b, err := json.Marshal(examples)
	if err != nil {
		panic(err)
	}
	return string(b)
}

// SchemaExampleQueries is the main schema's vgi.example_queries value: a JSON
// list of {description, sql} so each example carries a human-readable
// description (VGI506/VGI515). Every query parses an inline RSS document, so it
// runs with no network access.
var SchemaExampleQueries = exampleQueriesJSON(
	[2]string{
		"List the items parsed from an inline RSS 2.0 feed, ordered by position.",
		"SELECT seq, title, link FROM feed.main.feed_items('" + SampleRSS + "') ORDER BY seq;",
	},
	[2]string{
		"Count the items in an inline feed.",
		"SELECT count(*) AS items FROM feed.main.feed_items('" + SampleRSS + "');",
	},
	[2]string{
		"Read feed-level metadata: title, detected format, language, and item count.",
		"SELECT title, feed_type, language, item_count FROM feed.main.feed_info('" + SampleRSS + "');",
	},
	[2]string{composedNewEntriesDesc, composedNewEntriesSQL},
	[2]string{composedCategoryShareDesc, composedCategoryShareSQL},
)

// SampleMirrorJSON is a JSON Feed mirror of the same blog as SampleRSS that
// carries Second Post plus a Third Post the RSS feed lacks. It backs the
// composed links_in_both_feeds agent task (answer: https://query.farm/second).
const SampleMirrorJSON = `{"version":"https://jsonfeed.org/version/1.1","title":"Query Farm JSON Mirror",` +
	`"items":[{"id":"https://query.farm/second","url":"https://query.farm/second","title":"Second Post"},` +
	`{"id":"https://query.farm/third","url":"https://query.farm/third","title":"Third Post"}]}`

// SampleNotesAtom is a three-entry Atom feed in which only one entry has a
// category. It backs the composed uncategorized_entries agent task (answer:
// Farm Notes, 2).
const SampleNotesAtom = `<feed xmlns="http://www.w3.org/2005/Atom"><title>Farm Notes</title><id>urn:farm-notes</id>` +
	`<entry><title>Soil</title><id>urn:n1</id><category term="garden"/></entry>` +
	`<entry><title>Rain</title><id>urn:n2</id></entry>` +
	`<entry><title>Frost</title><id>urn:n3</id></entry></feed>`

// AgentTestTasks is the VGI152/VGI920 analyst-task suite (catalog tag
// vgi.agent_test_tasks). Each task is a natural-language prompt an agent should
// be able to satisfy using this worker. Only name + prompt are published
// (VGI416): each task's grader reference SQL lives in the private repo-root
// sidecar vgi-agent-tests.yaml, keyed by task name, which vgi-lint discovers on
// its own. Every task operates on inline feed documents (SampleRSS,
// SampleMirrorJSON, SampleNotesAtom) or the built-in registry, so `vgi-lint
// simulate` can execute them deterministically with NO network access. Keep the
// sidecar in sync when a prompt or one of those documents changes.
var AgentTestTasks = buildAgentTestTasks()

func buildAgentTestTasks() string {
	type task struct {
		Name   string `json:"name"`
		Prompt string `json:"prompt"`
	}
	// The single-object tasks are single-shape reads (direct column projection
	// or a simple equality filter). The two composed tasks at the end combine
	// objects (feed_items x feed_items across formats; feed_info + feed_items)
	// and reshape the result, so their prompts pin the exact output columns to
	// keep the exact-compare grader stable.
	tasks := []task{
		{
			Name: "list_item_titles",
			Prompt: "List the title of every entry in this RSS feed, in the order they " +
				"appear in the feed. Feed document: " + SampleRSS,
		},
		{
			Name: "list_item_links",
			Prompt: "List the link URL of each entry in this feed, in feed order. Feed " +
				"document: " + SampleRSS,
		},
		{
			Name: "first_item_summary",
			Prompt: "What is the summary (description) text of the FIRST entry in this " +
				"feed? Feed document: " + SampleRSS,
		},
		{
			Name: "detect_feed_type_and_title",
			Prompt: "For this feed document, what is its detected format (rss, atom, or " +
				"json) and its feed title? Feed document: " + SampleRSS,
		},
		{
			Name:   "feed_language",
			Prompt: "What language is this feed declared to be in? Feed document: " + SampleRSS,
		},
		{
			Name: "feed_item_count",
			Prompt: "According to this feed's own metadata, how many items does it report? " +
				"Read the feed-level item count. Feed document: " + SampleRSS,
		},
		{
			Name: "registry_json_feeds",
			Prompt: "This worker ships a built-in registry of well-known public feeds. " +
				"Using that registry, list the name of every feed that is published in " +
				"the JSON Feed (json) format.",
		},
		{
			Name: "links_in_both_feeds",
			Prompt: "A blog publishes the RSS feed and the JSON Feed below. Which entry " +
				"link URLs appear in BOTH feeds? Return a single column named link, one " +
				"row per URL, sorted ascending. RSS feed: " + SampleRSS +
				" JSON Feed: " + SampleMirrorJSON,
		},
		{
			Name: "uncategorized_entries",
			Prompt: "For the Atom feed below, report the feed's title and how many of its " +
				"entries have no category at all. Return exactly one row with two columns: " +
				"feed_title (text) and uncategorized_entries (integer). Atom feed: " +
				SampleNotesAtom,
		},
	}
	b, err := json.Marshal(tasks)
	if err != nil {
		panic(err)
	}
	return string(b)
}

// IMPORTANT: table-function state is gob-encoded by the SDK between NewState and
// Process (it may cross a process/worker boundary), so state structs must have
// EXPORTED, gob-encodable fields only — no arrow.RecordBatch, no interfaces, no
// channels/funcs, no unexported fields. Each function parses its feed eagerly in
// NewState, stores plain Go slices/structs in an embedded Cursor, and rebuilds
// the Arrow batch in Process.
//
// time.Time is gob-encodable; *time.Time is too (nil round-trips), which is how
// missing dates survive as NULL timestamps.
//
// WHY AN EXPLICIT CURSOR, NOT A bool Done (the HTTP-continuation fix):
//
// Over the stateless HTTP transport the worker keeps NO live state between
// Process ticks — the framework round-trips the producer state through an opaque
// continuation token: after each tick it gob-encodes the LIVE user state, the
// client returns the token, and the worker resumes by gob-decoding it. The HTTP
// server emits at most one data batch per response, so a producer with more to
// emit is always resumed mid-stream from its token. A bare `Done bool` flipped
// *after* the single Emit observes the pre-Emit snapshot on resume, re-emits the
// same rows forever, and pins the worker in an infinite loop (subprocess/unix
// hold live state in memory, so they never hit it). feed_items emits MANY rows,
// so this is mandatory, not cosmetic. The fix: each state embeds Cursor[T]
// carrying the fetched Rows plus the Offset of the next unemitted row; Process
// emits a bounded slice from Offset, advances Offset BEFORE yielding, and
// Finish()es once Offset >= len(Rows). The framework snapshots Offset into the
// token, so HTTP resumes correctly and terminates.

// rowsPerTick bounds how many rows each Process tick emits. Emitting a bounded
// slice and advancing the cursor is what makes the offset observable across the
// HTTP continuation boundary (and scales to large feeds).
const rowsPerTick = 256

// Cursor is the shared streaming cursor embedded by every table-function state:
// the eagerly fetched rows plus the offset of the next unemitted row. Both
// fields are exported so gob round-trips them through the HTTP continuation
// token. The TYPE is exported (Cursor, not cursor) because the SDK counts a
// state struct's exported FIELDS at registration to verify it is gob-encodable.
type Cursor[T any] struct {
	Rows   []T
	Offset int
}

// nextSlice returns the next bounded slice of rows to emit and advances the
// cursor past them. It reports done=true once all rows have been consumed, at
// which point Process should call out.Finish().
func (c *Cursor[T]) nextSlice() (slice []T, done bool) {
	if c.Offset >= len(c.Rows) {
		return nil, true
	}
	end := c.Offset + rowsPerTick
	if end > len(c.Rows) {
		end = len(c.Rows)
	}
	slice = c.Rows[c.Offset:end]
	c.Offset = end
	return slice, false
}

// tsType is plain TIMESTAMP (microsecond, no timezone) so DuckDB sees TIMESTAMP
// rather than TIMESTAMP WITH TIME ZONE.
var tsType = &arrow.TimestampType{Unit: arrow.Microsecond}

// buildTimestampArray builds a TIMESTAMP column; a nil *time.Time becomes NULL.
func buildTimestampArray(n int64, fn func(i int64) *time.Time) arrow.Array {
	b := array.NewTimestampBuilder(memory.DefaultAllocator, tsType)
	defer b.Release()
	b.Reserve(int(n))
	for i := int64(0); i < n; i++ {
		t := fn(i)
		if t == nil {
			b.AppendNull()
			continue
		}
		b.Append(arrow.Timestamp(t.UTC().UnixMicro()))
	}
	return b.NewArray()
}

// buildStringListArray builds a VARCHAR[] column. A nil slice yields an empty
// (non-NULL) list.
func buildStringListArray(n int64, fn func(i int64) []string) arrow.Array {
	b := array.NewListBuilder(memory.DefaultAllocator, arrow.BinaryTypes.String)
	defer b.Release()
	vb := b.ValueBuilder().(*array.StringBuilder)
	for i := int64(0); i < n; i++ {
		b.Append(true)
		for _, s := range fn(i) {
			vb.Append(s)
		}
	}
	return b.NewArray()
}

// isNullArg reports whether positional argument pos is present and NULL.
func isNullArg(args *vgi.Arguments, pos int) bool {
	if args == nil {
		return true
	}
	col, err := args.GetColumn(pos)
	if err != nil {
		return false
	}
	return col.Len() == 0 || col.IsNull(0)
}

